<script lang="ts">
  import { onMount } from 'svelte';
  import { api, query } from './api';
  import { exportComparison, type ComparisonReport } from './tagihanExport';
  interface Period { periode: number; dari: string; sampai: string }
  let periods: Period[] = [], period = '', remise = 1, report: ComparisonReport | null = null, search = '', differenceOnly = false, loading = false, error = '', generation = 0;
  let exporting = false, exportError = '';
  async function download() { if (!report || !visible.length || exporting) return; exporting = true; exportError = ''; try { await exportComparison(report, visible, search, differenceOnly); } catch { exportError = 'Gagal membuat file Excel. Silakan coba lagi.'; } finally { exporting = false; } }
  const money = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(n);
  $: visible = (report?.items || []).filter(x => (!differenceOnly || x.selisih !== 0) && [x.nik, x.nama, x.unit].some(v => v.toLocaleLowerCase('id').includes(search.trim().toLocaleLowerCase('id'))));
  onMount(() => { void initialize(); });
  async function initialize() { loading = true; try { const data = await api<{items: Period[]; sekarang: number | null}>('/admin/periode'); periods = data.items; period = String(data.sekarang && periods.some(p => p.periode === data.sekarang) ? data.sekarang : periods[0]?.periode || ''); if (period) await load(); else error = 'Belum ada periode yang tersedia.'; } catch (e) { error = (e as Error).message; } finally { loading = false; } }
  async function load() { if (!period) return; const current = ++generation; loading = true; error = ''; report = null; try { const result = await api<ComparisonReport>('/admin/tagihan-vs-rekap' + query({periode: period, remise})); if (current === generation) report = result; } catch (e) { if (current === generation) error = (e as Error).message; } finally { if (current === generation) loading = false; } }
</script>
<section class="panel comparison"><div class="section-heading"><div><p class="eyebrow">ADMINISTRASI / ANALISIS</p><h2>Tagihan vs Rekap</h2></div></div>
<p class="muted">Bandingkan tagihan Waserda dari laporan BackOffice dengan transaksi kredit anggota pada rentang terpilih. Selisih dapat memiliki penyebab bisnis dan tidak selalu berarti kesalahan.</p>
<div class="filters"><label>Periode<select bind:value={period} on:change={load} disabled={!periods.length}>{#each periods as p}<option value={String(p.periode)}>{p.periode} · {p.dari} – {p.sampai}</option>{/each}</select></label><label>Jenis periode<select bind:value={remise} on:change={load}><option value={1}>Remise I</option><option value={2}>Remise II</option><option value={3}>Bulanan</option></select></label></div>
{#if error}<div class="error" role="alert">{error} <button on:click={() => periods.length ? load() : initialize()}>Coba lagi</button></div>{/if}
{#if loading}<p class="muted" aria-live="polite">Memuat perbandingan…</p>{/if}
{#if report && !loading}<p class="range">Rentang transaksi: <strong>{report.dari} – {report.sampai}</strong></p>
<div class="comparison-stats"><div><span>Tagihan Waserda</span><strong>{money(report.tagihan)}</strong></div><div><span>Rekap kredit</span><strong>{money(report.rekap)}</strong></div><div><span>Selisih · Tagihan − Rekap</span><strong>{money(report.selisih)}</strong></div></div>
<div class="table-controls"><label class="search-label">Cari anggota<input bind:value={search} placeholder="Nama, NIK, atau unit kerja"/></label><label class="check"><input type="checkbox" bind:checked={differenceOnly}/> Hanya ada selisih</label></div>
<div class="export-row"><p class="muted">Menampilkan {visible.length} dari {report.items.length} anggota. Ekspor mengikuti pencarian dan filter.</p><button class="secondary" on:click={download} disabled={exporting || !visible.length}>{exporting ? 'Menyiapkan…' : 'Ekspor Excel (.xlsx)'}</button></div>{#if exportError}<div class="error" role="alert">{exportError}</div>{/if}
<div class="table-wrap"><table><thead><tr><th>NIK</th><th>Nama</th><th>Unit kerja</th><th>Tagihan Waserda</th><th>Rekap kredit</th><th>Selisih</th></tr></thead><tbody>{#each visible as item (item.nik)}<tr><td>{item.nik}</td><td>{item.nama || '—'}</td><td>{item.unit || '—'}</td><td>{money(item.tagihan)}</td><td>{money(item.rekap)}</td><td class:difference={item.selisih !== 0}>{money(item.selisih)}</td></tr>{:else}<tr><td colspan="6" class="empty">Tidak ada data yang sesuai.</td></tr>{/each}</tbody></table></div>{/if}</section>
<style>
.filters{display:grid;grid-template-columns:2fr 1fr;gap:16px;max-width:750px}.range{font-size:.85rem;color:#718477;margin:5px 0 18px}.comparison-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:20px}.comparison-stats>div{border:1px solid #dcebdd;border-radius:12px;padding:18px}.comparison-stats span{display:block;font-size:.75rem;color:#819087;margin-bottom:8px}.comparison-stats strong{font-family:Poppins,sans-serif;font-size:1.15rem}.table-controls{display:flex;align-items:end;gap:20px}.search-label{flex:1;max-width:420px}.table-controls .check{white-space:nowrap}.export-row{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.export-row p{margin:0}.export-row button{white-space:nowrap}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;min-width:740px;font-size:.82rem}th,td{padding:13px 10px;border-bottom:1px solid #e2ebe2;text-align:left}th{font-size:.68rem;color:#819087;text-transform:uppercase;letter-spacing:.06em}th:nth-child(n+4),td:nth-child(n+4){text-align:right;white-space:nowrap}td.difference{font-weight:700;color:#a15e16}.error button{text-decoration:underline;font-weight:bold}@media(max-width:650px){.filters,.comparison-stats{grid-template-columns:1fr}.filters{gap:0}.comparison-stats{gap:8px}.table-controls{align-items:stretch;flex-direction:column;gap:0}.export-row{align-items:stretch;flex-direction:column}}
</style>
